  const observableAims=[["Построить чертёж и обосновать решение с помощью геометрического свойства.","Сызба салып, шешімді геометриялық қасиетпен негіздеу."],["Самостоятельно восстановить шаг решения и проверить результат другим способом.","Шешудің бір қадамын өз бетінше орындап, нәтижені басқа тәсілмен тексеру."],["Отличить наблюдение от предположения и подобрать свидетельство для проверки объяснения.","Бақылауды болжамнан ажыратып, түсіндірмені тексеруге дерек таңдау."],["Описать положение объекта и объяснить закономерность с опорой на карту.","Нысанның орнын сипаттап, картаға сүйеніп заңдылықты түсіндіру."],["Установить связь между событием и его последствием, подтвердить вывод источником.","Оқиға мен салдары арасындағы байланысты анықтап, қорытындыны дерекпен растау."],["Объяснить смысл эпизода через поступок героя или деталь авторского текста.","Үзінді мағынасын кейіпкер әрекеті немесе мәтін бөлшегі арқылы түсіндіру."],["Сравнить два варианта высказывания и объяснить изменение формы или смысла.","Айтылымның екі нұсқасын салыстырып, тұлғасы не мағынасының өзгеруін түсіндіру."],["Выполнить алгоритм и проверить прогноз при изменении входных данных.","Алгоритмді орындап, бастапқы дерек өзгергендегі болжамды тексеру."],["Выбрать действие в заданной ситуации и обосновать его соответствующим правилом.","Жағдаятқа сай әрекет таңдап, оны ережемен негіздеу."],["Сравнить затраты и ожидаемый результат двух решений и объяснить выбор.","Екі шешімнің шығыны мен күтілетін нәтижесін салыстырып, таңдауды түсіндіру."],["Распознать повтор и изменение в музыкальном фрагменте и передать их ритмом.","Музыкалық үзіндідегі қайталау мен өзгерісті танып, ырғақпен көрсету."],["Показать последовательность движения и объяснить условия безопасного выполнения.","Қимыл ретін көрсетіп, қауіпсіз орындау шарттарын түсіндіру."],["Сравнить два законных хода с учётом возможного ответа соперника.","Қарсыластың ықтимал жауабын ескеріп, екі заңды жүрісті салыстыру."],["Сопоставить два эскиза и объяснить, как выбранная деталь влияет на результат.","Екі нобайды салыстырып, таңдалған бөлшектің нәтижеге ықпалын түсіндіру."]];
  function classroomActivity(bookId,topic,lang,subject,grade){
    if(/^(?:кеңістіктегі векторлар|векторы в пространстве|векторы в пространстве и их координаты)$/i.test(topic.trim())){
      return lang==='ru'?[
        'Найти координаты вектора и объяснить его направление.',
        'Даны точки A(1; −2; 3) и B(4; 0; −1). Как описать перемещение из A в B?',
        'Вычислите векторы AB и BA. Запишите правило вычитания координат и проверьте, что AB + BA = (0; 0; 0).',
        'AB = (3; 2; −4), BA = (−3; −2; 4). По одному баллу за каждый вектор и за проверку суммы. Типичная ошибка: вычесть конец из начала.',
        'Найдите координаты точки C, если вектор AC = (2; −1; 3). Проверьте подстановкой.'
      ]:[
        'Вектордың координаталарын тауып, бағытын түсіндіру.',
        'A(1; −2; 3) және B(4; 0; −1) нүктелері берілген. A-дан B-ға орын ауыстыруды қалай сипаттаймыз?',
        'AB және BA векторларын есептеңіз. Координаталарды азайту ережесін жазып, AB + BA = (0; 0; 0) екенін тексеріңіз.',
        'AB = (3; 2; −4), BA = (−3; −2; 4). Әр векторға және қосындыны тексеруге бір балдан. Жиі қате: бас нүктеден соңғы нүктені азайту.',
        'AC = (2; −1; 3) болса, C нүктесінің координаталарын тауып, орнына қою арқылы тексеріңіз.'
      ];
    }
    const authored=activityFor(bookId,topic,lang);
    if(authored)return authored;
    const ru=lang==='ru',book=TEXTBOOK_CATALOG.find(b=>b.id===bookId);
    const profile=subjectActivities.find(row=>new RegExp(row[0],'i').test(subject||book?.subject||''));
    const n=Number(String(grade||book?.grade||'').match(/\d+/)?.[0]||0);
    const practice=profile?.[ru?1:3]||(ru?'Выберите ситуацию по теме. Покажите два возможных действия и объясните, какое лучше отвечает условию.':'Тақырып бойынша жағдаят таңдаңыз. Екі әрекет ұсынып, қайсысы шартқа көбірек сай екенін түсіндіріңіз.');
    const assessment=profile?.[ru?2:4]||(ru?'Представлены два решения и критерий выбора.':'Екі шешім және таңдау өлшемі көрсетілген.');
    const level=n<=4?(ru?'Работайте с учителем на одном примере. Ответ можно показать рисунком или объяснить устно.':'Мұғаліммен бірге бір мысалды қараңыз. Жауапты суретпен көрсетіңіз немесе ауызша айтыңыз.'):n<=9?(ru?'Сначала выполните самостоятельно, затем проверьте один шаг в паре.':'Алдымен өз бетіңізше орындап, бір қадамды жұппен тексеріңіз.'):(ru?'Проверьте, при каком изменении условий ваш вывод перестанет выполняться.':'Шарт қалай өзгерсе қорытындыңыз орындалмайтынын тексеріңіз.');
    const aim=observableAims[subjectActivities.indexOf(profile)]?.[ru?0:1]||(ru?'Сравнить два решения задачи по теме и обосновать выбор по одному критерию.':'Тақырыптағы тапсырманың екі шешімін салыстырып, таңдауды бір өлшеммен негіздеу.');
    return [aim,(ru?'Исходный материал: «':'Бастапқы материал: «')+topic+'». '+level,practice,assessment,(ru?'Используйте другой пример по теме «':'«')+topic+(ru?'». ':'» тақырыбынан басқа мысал алыңыз. ')+practice];
  }
