  function getTopicIdeas(subject,grade,ru){const band=grade<=4?0:grade<=6?1:grade<=9?2:3,s=(subject||'').toLocaleLowerCase();let group='generic';if(/математ|алгебр|геометр/.test(s))group='math';else if(/цифр|информат|робот|stem/.test(s))group='informatics';else if(/дене шыны|физическ.*культур/.test(s))group='physical';else if(/тіл|әдебиет|language|язык|литератур|буквар|сауат ашу|грамот|алиф|елип/.test(s))group='language';else if(/биолог|физик|хими|жаратылыстану|естествозн|дүниетану|познание мира/.test(s))group='science';else if(/тарих|истори/.test(s))group='history';else if(/географ/.test(s))group='geography';else if(/өнер|искусств|музык|көркем|еңбек|технолог|графика|дизайн/.test(s))group='arts';const data=topicIdeas[group],bank=data[group==='math'?(ru?1:0):0],index=group==='math'?band:band+(ru?4:0);return bank?.[index]||topicIdeas.generic[0][ru?band+4:band]}
