        const list=document.createElement('div');
        resources.append(resourceHeading,list,form.querySelector('.pb-materials'));result.prepend(resources);
        function showTopicMaterials(){
          list.replaceChildren();
          const topic=topicField.value.trim(),lang=docLang.value,r=lang==='ru';
          if(!topic)return;
          const offer=(item)=>{
            const row=document.createElement('p'),link=document.createElement('a'),button=document.createElement('button');
            link.href=item.url;link.target='_blank';link.rel='noopener';link.textContent=item.title;
            button.type='button';button.className='secondary';button.textContent=ru?'Добавить в план':'Жоспарға қосу';
            button.disabled=materials.some(m=>m.url===item.url);
            button.onclick=()=>{materials.push(item);renderMaterials();saveDraft();showTopicMaterials();};
            row.append(link,' ',button);list.append(row);
          };
          for(const [type,kind,label] of [['slides',0,r?'Слайды для обсуждения':'Талқылауға арналған слайдтар'],['map',7,r?'Схема для заполнения':'Толтыруға арналған сызба']]){
            const url=new URL(location.pathname,location.href);url.hash=new URLSearchParams({resource:type,topic,lang,book:picker.value,subject:readData().fields[0],grade:gradeSelect.value}).toString();
            offer({kind,title:label+' · '+topic,url:url.href,note:''});
          }
          const selected=activeTopics[selectedTopicIndex];const paragraphSource=selected?.[1]===topic?selected[4]:null;
          if(paragraphSource&&safeUrl(paragraphSource.url)){
            const row=selected;
            offer({kind:6,title:(paragraphSource.partial?(r?'Оглавление учебника':'Оқулық мазмұны'):(r?'Электронный учебник':'Электрондық оқулық'))+' · '+topic,url:paragraphSource.url,note:row[2]?(r?'Страница ':'Бет ')+row[2]:''});
          }
          const library=typeof remoteMaterials==='undefined'?[]:remoteMaterials;
          for(const m of library.filter(m=>m.language===lang&&[m.title,m.description].join(' ').toLocaleLowerCase().includes(topic.toLocaleLowerCase())&&!/^(КСП|ҚМЖ):/.test(m.title))){
            offer({kind:m.kind==='video'?1:m.kind==='presentation'?0:m.mime?.startsWith('image/')?7:6,title:m.title,url:safeUrl(m.source_url)||new URL('/view/'+encodeURIComponent(m.id),location.href).href,note:''});
          }
        }
        resources.addEventListener('toggle',()=>{if(resources.open)showTopicMaterials();});
        form.addEventListener('change',()=>{if(resources.open)showTopicMaterials();});
