    const labels=()=>{textbookButton.textContent=uiRu()?'План по учебнику 📖':'Оқулық бойынша жоспар 📖';const ru=uiRu(),a=ru?'Создать план урока':'Сабақ жоспарын жасау',b=ru?'Подробный план ✎':'Толық жоспар ✎';if(quickButton.textContent!==a)quickButton.textContent=a;if(detailedButton.textContent!==b)detailedButton.textContent=b;};
